<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Jost:wght@400;500;700&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#E34234; --blue:#204EA2; --yellow:#F5C518;
    --black:#111111; --white:#FAFAF7; --grey:#D8D8D4;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    font-family:'Jost',sans-serif;
    background:var(--white); color:var(--black);
    line-height:1.5;
  }
  /* ---- Mondrian grid layout ---- */
  .frame{
    display:grid;
    grid-template-columns:repeat(12,1fr);
    grid-auto-rows:minmax(64px,auto);
    gap:0;
    min-height:100vh;
  }
  .cell{border:0 solid var(--black); padding:2rem}
  .b-r{border-right-width:6px} .b-b{border-bottom-width:6px}
  .b-t{border-top-width:6px} .b-l{border-left-width:6px}

  header.hero{
    grid-column:1/13; grid-row:1/3;
    background:var(--white);
    display:flex; flex-direction:column; justify-content:center;
    padding:3rem 2.5rem;
  }
  .kicker{
    font-weight:500; letter-spacing:.35em; text-transform:uppercase;
    font-size:.8rem; margin-bottom:1rem;
  }
  .kicker span{color:var(--red)}
  h1{
    font-weight:700; font-size:clamp(1.8rem,4.5vw,3.4rem);
    line-height:1.1; max-width:22ch;
  }
  .hero p{max-width:52ch; margin-top:1rem; font-size:1.05rem}

  .canvas-cell{
    grid-column:1/8; grid-row:3/6;
    background:var(--white);
    position:relative; overflow:hidden;
  }
  #scene{position:absolute; inset:0; width:100%; height:100%; display:block}
  .canvas-cell figcaption{
    position:absolute; left:0; bottom:0;
    background:var(--black); color:var(--white);
    font-size:.75rem; letter-spacing:.15em; text-transform:uppercase;
    padding:.4rem .9rem;
  }

  .red-block{grid-column:8/13; grid-row:3/4; background:var(--red)}
  .blue-block{grid-column:8/11; grid-row:4/5; background:var(--blue)}
  .yellow-block{grid-column:11/13; grid-row:4/5; background:var(--yellow)}

  .facts{
    grid-column:1/8; grid-row:6/8;
    background:var(--white);
  }
  .facts h2, .story h2, .why h2{
    font-weight:700; font-size:1.4rem; margin-bottom:.8rem;
    text-transform:uppercase; letter-spacing:.08em;
  }
  .facts dl{display:grid; grid-template-columns:auto 1fr; gap:.35rem 1.2rem}
  .facts dt{font-weight:700}
  .facts dd{margin:0}

  .story{grid-column:8/13; grid-row:5/7; background:var(--white)}
  .story p{margin-bottom:.9rem}

  .why{
    grid-column:1/13; grid-row:8/9;
    background:var(--black); color:var(--white);
  }
  .why h2{color:var(--yellow)}
  .why p{max-width:70ch}
  .why em{font-style:normal; color:var(--red); font-weight:500}

  .cta{
    grid-column:1/13; grid-row:9/10;
    background:var(--white);
    display:flex; flex-wrap:wrap; align-items:center; gap:1.5rem;
  }
  .cta a.btn{
    display:inline-block; text-decoration:none;
    background:var(--red); color:var(--white);
    font-weight:700; letter-spacing:.12em; text-transform:uppercase;
    padding:1rem 2rem; border:3px solid var(--black);
  }
  .cta a.btn:hover{background:var(--blue)}
  .cta .src{font-size:.9rem}
  .cta .src a{color:var(--blue)}

  @media (max-width:760px){
    .frame{grid-template-columns:1fr}
    .cell{grid-column:1/-1 !important; grid-row:auto !important}
    .canvas-cell{min-height:340px}
  }
</style>
</head>
